import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  const stats = { totalStudents: '1,250', totalTeachers: '45', activeClasses: '120', inactiveStudents: '25' };

  const growthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  };

  return (
    <div style={{ display: 'flex', flex: 1, width: '100%', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 කොළ පාට සයිඩ්බාර් එක - Header එකට යටින් පටන් අරන් Footer එක ගාවටම යනවා */}
      <div style={{
        width: '260px',
        backgroundColor: '#15803d',
        color: '#ffffff',
        display: 'flex',
        flexDirection: 'column',
        padding: '20px 0',
        boxSizing: 'border-box'
      }}>
        <div style={{ padding: '0 25px 15px 25px', borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
          <h2 style={{ fontSize: '18px', fontWeight: 'bold', margin: 0 }}>Admin Panel</h2>
        </div>

        <nav style={{ flex: 1, marginTop: '20px', display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 10px' }}>
          {menuItems.map((item) => {
            const isActive = currentSubPage === item.name;
            return (
              <button
                key={item.name}
                onClick={() => setCurrentSubPage(item.name)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '12px',
                  width: '100%',
                  padding: '12px 15px',
                  backgroundColor: isActive ? 'rgba(0, 0, 0, 0.2)' : 'transparent',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontSize: '14px',
                  fontWeight: isActive ? '600' : '500'
                }}
              >
                <span>{item.icon}</span>
                <span>{item.name}</span>
              </button>
            );
          })}
        </nav>
      </div>

      {/* ⚪ දකුණු පැත්තේ ප්‍රධාන කොටස */}
      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', backgroundColor: '#f8fafc' }}>
        
        {/* 👤 Header එකට කෙලින්ම යටින් දකුණු පැත්තේ එන Welcome Admin සහ Logout තීරුව */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          padding: '15px 30px',
          borderBottom: '1px solid #e2e8f0',
          backgroundColor: '#ffffff'
        }}>
          {/* Welcome Admin කෑල්ල */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '32px', height: '32px', backgroundColor: '#e2e8f0', borderRadius: '50%', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>👤</div>
            <span style={{ fontWeight: '600', color: '#1e293b', fontSize: '14px' }}>Welcome, admin 👋</span>
          </div>

          {/* Logout බටන් එක */}
          <button 
            onClick={handleLogout}
            style={{ 
              backgroundColor: '#dc2626', color: '#ffffff', border: 'none', padding: '10px 18px', borderRadius: '8px', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '6px', fontWeight: 'bold', fontSize: '13px'
            }}
          >
            <span>🚪</span> Logout
          </button>
        </div>

        {/* 📊 Content කොටස */}
        <div style={{ padding: '30px', display: 'flex', flexDirection: 'column', gap: '25px', flex: 1 }}>
          
          {currentSubPage === 'Overview' && (
            <>
              {/* Cards */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px' }}>
                {[
                  { t: 'Total Students', v: stats.totalStudents, i: '👨‍🎓' },
                  { t: 'Total Teachers', v: stats.totalTeachers, i: '👩‍🏫' },
                  { t: 'Active Classes', v: stats.activeClasses, i: '🏫' },
                  { t: 'Inactive Students', v: stats.inactiveStudents, i: '⚠️' }
                ].map((card, i) => (
                  <div key={i} style={{ background: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 4px 0' }}>{card.t}</p>
                      <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px' }}>{card.v}</h2>
                    </div>
                    <span style={{ fontSize: '24px', opacity: 0.7 }}>{card.i}</span>
                  </div>
                ))}
              </div>

              {/* Chart */}
              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '20px' }}>
                <div style={{ background: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px' }}>
                    <h3 style={{ margin: 0, fontSize: '14px', color: '#1e293b' }}>Enrollment Growth Overview</h3>
                    <span style={{ backgroundColor: '#e0f2fe', color: '#0369a1', padding: '3px 10px', borderRadius: '20px', fontSize: '11px' }}>LKR 450,000</span>
                  </div>
                  <div style={{ height: '200px' }}><Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} /></div>
                </div>

                <div style={{ background: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
                  <h3 style={{ margin: '0 0 15px 0', fontSize: '14px' }}>Student Status</h3>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    {[{ name: 'Ruwan Name', status: 'Active', bg: '#22c55e' }, { name: 'John Name', status: 'Active', bg: '#22c55e' }, { name: 'Sama Name', status: 'Inactive', bg: '#ef4444' }].map((s, i) => (
                      <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '6px 0', borderBottom: '1px solid #f1f5f9', fontSize: '13px' }}>
                        <span>{s.name}</span><span style={{ backgroundColor: s.bg, color: '#fff', padding: '2px 6px', borderRadius: '4px', fontSize: '11px' }}>{s.status}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Schedule Table */}
              <div style={{ background: '#ffffff', padding: '20px', borderRadius: '12px', border: '1px solid #f1f5f9' }}>
                <h3 style={{ margin: '0 0 15px 0', fontSize: '14px' }}>Upcoming Class Schedule</h3>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
                  <thead>
                    <tr style={{ borderBottom: '2px solid #f1f5f9', textAlign: 'left' }}>
                      <th style={{ padding: '8px' }}>Time</th><th>Sun</th><th>Mon</th><th>Wed</th><th>Thu</th><th>Fri</th>
                    </tr>
                  </thead>
                  <tbody>
                    {[
                      { time: '10:00', sun: '', mon: 'Math 101', wed: '', thu: '', fri: '' },
                      { time: '11:00', sun: 'Wedneddiel', mon: '', wed: 'Science', thu: 'English Lit', fri: '' }
                    ].map((row, i) => (
                      <tr key={i} style={{ borderBottom: '1px solid #f1f5f9' }}>
                        <td style={{ padding: '10px 8px', fontWeight: '600' }}>{row.time}</td>
                        <td>{row.sun && <span style={{ backgroundColor: '#15803d', color: '#fff', padding: '3px 6px', borderRadius: '4px' }}>{row.sun}</span>}</td>
                        <td>{row.mon && <span style={{ backgroundColor: '#166534', color: '#fff', padding: '3px 6px', borderRadius: '4px' }}>{row.mon}</span>}</td>
                        <td>{row.wed && <span style={{ backgroundColor: '#f59e0b', color: '#fff', padding: '3px 6px', borderRadius: '4px' }}>{row.wed}</span>}</td>
                        <td>{row.thu && <span style={{ backgroundColor: '#10b981', color: '#fff', padding: '3px 6px', borderRadius: '4px' }}>{row.thu}</span>}</td>
                        <td>{row.fri && <span style={{ backgroundColor: '#8b5cf6', color: '#fff', padding: '3px 6px', borderRadius: '4px' }}>{row.fri}</span>}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              {/* 🔘 බටන් 3 තීරුව (කිසිම සුදු පාට පසුබිම් කොටුවක් නෑ, Layout එක උඩ විතරමයි බටන් තියෙන්නේ) */}
              <div style={{ display: 'flex', gap: '15px', marginTop: '5px' }}>
                <button style={{ backgroundColor: '#15803d', color: 'white', border: 'none', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>
                  Manage Students
                </button>
                <button style={{ backgroundColor: '#ffffff', color: '#475569', border: '1px solid #cbd5e1', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '13px' }}>
                  Manage Teachers
                </button>
                <button style={{ backgroundColor: '#ffffff', color: '#475569', border: '1px solid #cbd5e1', padding: '12px 24px', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '13px' }}>
                  Create New Course
                </button>
              </div>
            </>
          )}

          {/* Subpages */}
          {currentSubPage === 'Students' && <div><h2>👨‍🎓 Student Management</h2></div>}
          {currentSubPage === 'Teachers & Classes' && <div><h2>🏫 Teachers & Classes</h2></div>}
          {currentSubPage === 'Reports' && <div><h2>📋 Academic Reports</h2></div>}
          {currentSubPage === 'Settings' && <div><h2>⚙️ System Settings</h2></div>}
        </div>
      </div>
    </div>
  );
}
